def numWays(words, target):
    MOD = 10 ** 9 + 7
    m = len(words[0])
    n = len(target)
    cnt = [[0] * 26 for _ in range(m)]
    for w in words:
        for i, ch in enumerate(w):
            cnt[i][ord(ch) - 97] += 1
    dp = [0] * (n + 1)
    dp[0] = 1
    for i in range(m):
        for j in range(min(i + 1, n), 0, -1):
            dp[j] = (dp[j] + dp[j - 1] * cnt[i][ord(target[j - 1]) - 97]) % MOD
    return dp[n] % MOD
